import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { User } from './user.entity';
import { Role } from '../role/role.entity';
import { Permissions } from '../permissions/permissions.entity';

@Injectable()
export class UserService {
  constructor(
    @InjectRepository(User)
    private readonly userRepository: Repository<User>,
    @InjectRepository(Role)
    private readonly roleRepository: Repository<Role>,
    @InjectRepository(Permissions)
    private readonly permissionsRepository: Repository<Permissions>
  ) {}

  async getRoleById(id: number) {
    return await this.roleRepository.findOne({ where: { id } });
  }

  async getUserByPermissionId(permissionId: number): Promise<User> {
    const user = await this.userRepository.findOne({ relations: ['roles', 'permissions'] });
    if (user && user.permissions.some(p => p.id === permissionId)) {
      return user;
    }
    return null;
  }
}

// user.entity.ts
import { Entity, PrimaryGeneratedColumn, Column, ManyToMany, JoinTable } from 'typeorm';
import { Role } from '../role/role.entity';
import { Permissions } from '../permissions/permissions.entity';

@Entity()
export class User {
  @PrimaryGeneratedColumn('uuid')
  id: string;

  @Column()
  name: string;

  @ManyToMany(() => Role, role => role.users)
  roles: Role[];

  @ManyToMany(() => Permissions, permission => permission.user)
  permissions: Permissions[];
}

// role.entity.ts
